function needsWrittenReview(m){const t=[m.title,m.story,m.context,m.task,m.steps,m.evidence_goal,m.success_criterion,m.teacher_note,m.raw_text].map(x=>JSON.stringify(x||'')).join(' ').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');return writtenPatterns.some(p=>new RegExp(p).test(t));}
