// PRISMA: Obtiene el codigo de participante activo para la Ruta Adaptativa.
function participantId(){return String(session?.code||'default').toLowerCase().replace(/[^a-z0-9_-]+/g,'-')}
// PRISMA: Escapa texto antes de insertarlo en HTML para evitar que contenido externo se interprete como codigo.
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
// PRISMA: Muestra mensajes breves en los modulos.
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2600)}
// PRISMA: Envia una solicitud JSON autenticada al servidor local.
async function post(path,payload){if(location.protocol==='file:')return null;try{const body={...payload,session_id:payload?.session_id||window.PRISMA_RESEARCH?.sessionId?.()||''};const res=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json',...(session?.studentToken?{'X-PRISMA-Student-Token':session.studentToken}:{})},body:JSON.stringify(body)});const data=await res.json().catch(()=>null);return res.ok?data:null}catch{return null}}
// PRISMA: Limpia marcas de formato no deseadas antes de mostrar texto generado.
function cleanDisplay(text){let t=String(text||'').replace(/\r/g,'');t=t.replace(/```(?:json|markdown|text)?/gi,'').replace(/```/g,'').replace(/\*\*/g,'').replace(/__/g,'').replace(/`/g,'');t=t.replace(/^\s*#{1,6}\s*/gm,'').replace(/^\s*[-*+]\s+/gm,'• ').replace(/\n{3,}/g,'\n\n');const labelsMap={'TITULO:':'Título:','HISTORIA:':'Situación:','CONTEXTO:':'Contexto:','RETO:':'Reto:','PASO 1:':'1.','PASO 2:':'2.','PASO 3:':'3.','PASO 4:':'4.','MODULOS:':'Módulos sugeridos:','NOTA DOCENTE:':'Orientación docente:','FOCO:':'Foco:','APOYO:':'Nivel de apoyo:','EVIDENCIA:':'Evidencia esperada:','CRITERIO DE EXITO:':'Criterio de éxito:','COMPRENSION:':'Comprensión:','DISENO:':'Diseño:','JUSTIFICACION:':'Justificación:','VERIFICACION:':'Verificación:','RETROALIMENTACION:':'Retroalimentación:','FORTALEZA 1:':'Fortaleza:','FORTALEZA 2:':'Fortaleza:','POR FORTALECER 1:':'Por fortalecer:','POR FORTALECER 2:':'Por fortalecer:','MEJORA 1:':'Mejora:','MEJORA 2:':'Mejora:','OBJETIVO DE APRENDIZAJE:':'Objetivo de aprendizaje:','RUTA PASO 1:':'Ruta 1:','RUTA PASO 2:':'Ruta 2:','RUTA PASO 3:':'Ruta 3:','MINI RETO:':'Mini-reto:','PROXIMA MISION:':'Próxima misión:','SUGERENCIA DOCENTE:':'Sugerencia docente:'};for(const [a,b] of Object.entries(labelsMap))t=t.replace(new RegExp('^'+a.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gmi'),b);return t.trimStart()}
// PRISMA: Lee el streaming NDJSON de Gemma y separa tokens, resultado final y errores.
async function streamNdjson(path,payload,onText){if(location.protocol==='file:')return null;try{const body={...payload,session_id:payload?.session_id||window.PRISMA_RESEARCH?.sessionId?.()||''};const res=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json',...(session?.studentToken?{'X-PRISMA-Student-Token':session.studentToken}:{})},body:JSON.stringify(body)});if(!res.ok){const error=await res.json();throw new Error(error.detail||'No se pudo obtener el reto.');}const reader=res.body.getReader(),decoder=new TextDecoder();let pending='',raw='',finalData=null;for(;;){const {value,done}=await reader.read();pending+=decoder.decode(value||new Uint8Array(),{stream:!done});let lines=pending.split('\n');pending=lines.pop()||'';for(const line of lines){if(!line.trim())continue;let evt=null;try{evt=JSON.parse(line)}catch{continue}if(evt.type==='token'){raw+=evt.text||'';if(onText){onText(cleanDisplay(raw));await new Promise(resolve=>setTimeout(resolve,16));}}else if(evt.type==='reset'){raw='';if(onText)onText('')}else if(evt.type==='result')finalData=evt.data||null}if(done)break}if(pending.trim()){try{const evt=JSON.parse(pending);if(evt.type==='result')finalData=evt.data||null}catch{}}return finalData}catch(error){throw error}}
