// PRISMA: Reconstruye el texto completo de la mision a partir de sus campos estructurados.
function completeMissionText(m){
  if(!m)return '';
  const raw=cleanDisplay(m.raw_text||'').trim();
  if(raw)return raw;
  const steps=Array.isArray(m.steps)?m.steps:[];
  const tags=Array.isArray(m.module_tags)?m.module_tags:[];
  const lines=[
    m.title?`Título: ${m.title}`:'',
    m.story?`Situación: ${m.story}`:'',
    m.context?`Contexto: ${m.context}`:'',
    m.task?`Reto: ${m.task}`:'',
    ...steps.map((x,i)=>`${i+1}. ${x}`),
    m.evidence_goal?`Qué debes entregar: ${m.evidence_goal}`:'',
    m.success_criterion?`Criterio de éxito: ${m.success_criterion}`:'',
    tags.length?`Módulos relacionados: ${tags.join(', ')}`:'',
    m.teacher_note?`Nota de acompañamiento: ${m.teacher_note}`:''
  ].filter(Boolean);
  return cleanDisplay(lines.join('\n\n')).trim();
}
