    const payload={participant_code:session.code,grade:session.grade,mission_number:(s.model.missionCount||0)+1+missionCursor,focus:s.focus,mastery:s.model.mastery,debt:s.model.debt,recommendations:s.recommendations,adaptive_route:s.route,trajectory:s.trajectory,complexity:s.focus.complexity,parent_mission_id:parent,policy_version:window.PRISMA_ADAPTIVE.getPolicy().version,evidence_summary:s.model.competence,last_evaluation:last,learner_context:session.learnerContext||{},use_ai:false,application_module:new URLSearchParams(location.search).get("application")||""};
    if(serverHealth?.status==='ok')out=await streamNdjson('/api/generate_mission_stream',payload,text=>{const box=$('missionLiveText');$('missionTitle').textContent=text?'Escribiendo tu nuevo reto…':'Preparando un reto alternativo…';box.textContent=text||'Preparando un reto de razonamiento escrito…';box.scrollTop=box.scrollHeight;});
