// PRISMA: Completa valores de la ruta de aprendizaje cuando faltan en la evaluacion.
function learningDefaults(weakest){
  const plans={
    problem:{goal:'Comprender el problema antes de proponer soluciones.',route:['Aclara problema, causas, variables y restricciones en tu respuesta.','Practica identificación de datos y variables en un microrefuerzo PRISMA.','Aplica esa lectura del problema en una situación nueva.'],micro:'Escribe una ficha breve: problema, dos causas, dos variables medibles y una restricción.',success:'Se distinguen claramente causas, variables y restricciones.',next:'La siguiente misión comprobará si analizas primero la situación antes de diseñar.'},
    solution:{goal:'Convertir una idea general en una solución concreta, ordenada y realizable.',route:['Reescribe la solución como decisiones ordenadas usando los datos del caso.','Practica comparación de alternativas, algoritmos escritos y justificación.','Transfiere lo aprendido a un nuevo reto con mayor autonomía.'],micro:'Escribe cinco elementos de tu propuesta: datos, operaciones, decisión, resultado esperado y un posible error.',success:'Otra persona podría comprender y revisar tus decisiones sin adivinar pasos importantes.',next:'La siguiente misión pedirá diseñar una solución y anticipar una falla o alternativa.'},
    context:{goal:'Justificar la viabilidad de la propuesta para el contexto y los recursos disponibles.',route:['Agrega dos razones de viabilidad y una limitación real.','Practica una actividad contextual de ambiente, energía, fuerzas o recursos.','Compara dos alternativas y defiende la más pertinente.'],micro:'Compara dos soluciones usando costo o recursos, seguridad y efecto en la comunidad escolar.',success:'La elección usa criterios del contexto y reconoce al menos una limitación.',next:'La siguiente misión pedirá elegir entre alternativas y justificar la decisión.'},
    check:{goal:'Comprobar una propuesta con datos, criterios de éxito y una decisión de mejora.',route:['Indica qué medirás antes, qué medirás después y cómo compararás.','Practica medición, datos, ciencia u Ohm en un microrefuerzo.','Diseña una nueva solución incorporando la prueba desde el inicio.'],micro:'Diseña una prueba A/B: variable, unidad, valor antes, valor después y criterio de mejora.',success:'La prueba permite tomar una decisión concreta de mantener, modificar o descartar.',next:'La siguiente misión exigirá un plan de verificación desde el inicio.'}
  };return plans[weakest]||plans.problem
}
// PRISMA: Genera una evaluacion local de respaldo para una respuesta escrita.
function localRubric(answer){const text=String(answer||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');const token=new Set(text.match(/[a-z0-9]+/g)||[]),wordCount=words(answer).length;const count=arr=>arr.reduce((sum,w)=>sum+(token.has(w)?1:0),0);const lvl=p=>p>=3.2?4:p>=2.2?3:p>=1.25?2:1;const problem=lvl(Math.min(1.6,wordCount/55)+Math.min(1.3,count(['problema','causa','variable','necesidad','afecta','porque','riesgo','restriccion','objetivo'])*.45));const solution=lvl(Math.min(1.45,wordCount/60)+Math.min(1.4,count(['proponer','disenar','construir','implementar','usar','programar','organizar','crear','reducir','mejorar','solucion'])*.42)+Math.min(.7,count(['primero','luego','despues','finalmente','paso'])*.28));const context=lvl(Math.min(1.15,wordCount/75)+Math.min(1.65,count(['colegio','escuela','estudiante','docente','comunidad','recurso','costo','seguridad','ambiente','local','aula'])*.4));const check=lvl(Math.min(1,wordCount/85)+Math.min(2.1,count(['medir','medicion','comparar','comprobar','verificar','prueba','probar','dato','datos','registrar','antes','despues','resultado','evidencia'])*.43));const rubric={problem,solution,context,check};const weakest=Object.entries(rubric).sort((a,b)=>a[1]-b[1])[0][0];const plan=learningDefaults(weakest);return{rubric,rubric_details:Object.fromEntries(Object.entries(rubric).map(([k,v])=>[k,{level:v,evidence:'Evaluación local de respaldo.'}])),weakest,feedback:`La principal oportunidad de mejora está en ${labels[weakest]||weakest}.`,strengths:[],weaknesses:[],improvements:[plan.route[0]],learning_goal:plan.goal,learning_route:plan.route,micro_challenge:plan.micro,success_criterion:plan.success,next_mission_focus:plan.next,teacher_suggestion:'Permite revisar el mismo reto y después transferir lo aprendido a una misión nueva.',model_used:false,provisional:true,evaluation_source:'reglas-locales-respaldo'}}
// PRISMA: Convierte listas de feedback en elementos HTML seguros.
